package com.ghaniram.zoya

import android.app.Application
import android.content.Intent
import android.net.Uri
import androidx.core.content.ContextCompat
import com.ghaniram.zoya.data.local.AnuDataRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID

object ZoyaSessionManager {
    private lateinit var app: Application
    private val _state = MutableStateFlow(ZoyaUiState())
    val state: StateFlow<ZoyaUiState> = _state
    private var client: GeminiLiveClient? = null
    private var audioEngine: AudioEngine? = null
    private var modelSpeaking = false
    private var initialized = false
    private val repository by lazy { AnuDataRepository.getInstance(app) }
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private val phoneControls by lazy { PhoneControlManager(app) }
    private val prefs by lazy { app.getSharedPreferences("anu_session", 0) }
    private val idleQuotes = mapOf(ZoyaLanguage.ODIA to listOf("କୁହ କଣ ହେଲା? ମୁଁ ସବୁ ଶୁଣୁଛି।", "କଣ କରିବା ଦରକାର କୁହ, ମୁଁ ପ୍ରସ୍ତୁତ।"), ZoyaLanguage.ENGLISH to listOf("Go ahead, I'm listening.", "What can I do for you?"), ZoyaLanguage.HINDI to listOf("बोलिए, मैं सुन रही हूँ।", "आपके लिए क्या करूँ?"), ZoyaLanguage.SANTALI to listOf("ᱤᱧ ᱥᱟᱶ ᱜᱟᱞᱢᱟᱨᱟᱣ ᱢᱮ ᱾"))
    fun initialize(application: Application) { app = application; if (initialized) return; initialized = true; val language = runCatching { ZoyaLanguage.valueOf(prefs.getString("language", ZoyaLanguage.ODIA.name) ?: ZoyaLanguage.ODIA.name) }.getOrDefault(ZoyaLanguage.ODIA); _state.value = ZoyaUiState(language = language, quote = idleQuotes[language]?.random().orEmpty()); scope.launch { runCatching { repository.allMemoriesFlow.collect { memories -> _state.update { it.copy(memories = memories) } } } }; scope.launch { runCatching { repository.allChatMessagesFlow.collect { messages -> _state.update { it.copy(chatMessages = messages) } } } } }
    fun setLanguage(lang: ZoyaLanguage) { ensureInitialized(); prefs.edit().putString("language", lang.name).apply(); _state.update { it.copy(language = lang, quote = idleQuotes[lang]?.random().orEmpty()) }; if (isConnected()) reconnect() }
    fun connect() { ensureInitialized(); prefs.edit().putBoolean("active", true).apply(); startForegroundService(); connectInternal() }
    fun disconnect() { ensureInitialized(); prefs.edit().putBoolean("active", false).apply(); client?.disconnect(); audioEngine?.release(); client = null; audioEngine = null; modelSpeaking = false; stopForegroundService(); _state.update { it.copy(connectionState = ConnectionState.DISCONNECTED, inputLevel = 0f, outputLevel = 0f, isAnuResponding = false) } }
    fun startVisionSession() { ensureInitialized(); prefs.edit().putBoolean("active", true).apply(); startForegroundService(); if (!isConnected()) connectInternal() }
    fun sendVisionFrame(base64Jpeg: String) { ensureInitialized(); if (base64Jpeg.isNotBlank() && isConnected() && _state.value.isVisionActive) client?.sendVideoFrame(base64Jpeg) }
    fun restoreIfNeeded() { ensureInitialized(); if (prefs.getBoolean("active", false) && !isConnected()) connectInternal() }
    fun setVisionActive(active: Boolean) { ensureInitialized(); _state.update { it.copy(isVisionActive = active, visionDescription = if (active) it.visionDescription else if (it.visionDescription.isBlank()) "Live Vision is OFF. The last camera observation is historical, not current." else it.visionDescription) }; if (isConnected()) client?.sendText(if (active) "[VISION STATE] Live Vision is ON. Current camera frames may be used as current visual evidence." else "[VISION STATE] Live Vision is OFF. You cannot currently see through the camera. Any earlier camera observation is PAST/HISTORICAL only. Never claim to see the user's current surroundings.") }
    fun setVisionDescription(description: String) { _state.update { it.copy(visionDescription = description) } }
    fun sendText(text: String) { ensureInitialized(); val clean = text.trim(); if (clean.isBlank()) return; val proactive = clean.startsWith("[PROACTIVE SYSTEM EVENT]"); if (!proactive) { ProactiveEventEngine.noteUserActivity(); val msg = ChatMessage(UUID.randomUUID().toString(), ChatRole.USER, clean, System.currentTimeMillis()); _state.update { it.copy(chatMessages = it.chatMessages + msg, error = null, isAnuResponding = true) }; scope.launch { repository.saveChatMessage(msg) } } else _state.update { it.copy(error = null, isAnuResponding = true) }; val key = runCatching { AnuSettingsStore.getInstance(app).customGeminiKey.trim() }.getOrDefault(""); if (key.isBlank()) { if (!proactive) { val msg = ChatMessage(UUID.randomUUID().toString(), ChatRole.ANU, "Please add your Gemini API key in Settings.", System.currentTimeMillis()); _state.update { it.copy(chatMessages = it.chatMessages + msg, isAnuResponding = false) }; scope.launch { repository.saveChatMessage(msg) } }; return }; if (!isConnected()) connectInternal(); client?.sendText(clean) }
    fun addTask(title: String, time: String) { val task = AnuTask(UUID.randomUUID().toString(), title, time, false); _state.update { it.copy(tasks = it.tasks + task) }; AnuTaskAlarmScheduler.schedule(app, task) }
    fun toggleTask(id: String) { val task = _state.value.tasks.firstOrNull { it.id == id } ?: return; val updated = task.copy(isCompleted = !task.isCompleted); _state.update { s -> s.copy(tasks = s.tasks.map { if (it.id == id) updated else it }) }; if (updated.isCompleted) AnuTaskAlarmScheduler.cancel(app, id) else AnuTaskAlarmScheduler.schedule(app, updated) }
    fun deleteTask(id: String) { AnuTaskAlarmScheduler.cancel(app, id); _state.update { s -> s.copy(tasks = s.tasks.filterNot { it.id == id }) } }
    fun clearMemories() { scope.launch { repository.clearMemories() } }
    fun clearChatHistory() { scope.launch { repository.clearChatMessages() } }
    fun dismissError() { _state.update { it.copy(error = null) } }
    fun onApiKeyUpdated(newKey: String) { if (newKey.isNotBlank()) _state.update { it.copy(error = null) } }
    fun onSettingsUpdated() { if (isConnected()) reconnect() }
    fun reconnectForCriticalSettings() { if (isConnected()) reconnect() }
    private fun connectInternal() { val settings = runCatching { AnuSettingsStore.getInstance(app) }.getOrNull(); val apiKey = settings?.customGeminiKey?.trim().orEmpty(); if (apiKey.isBlank()) { _state.update { it.copy(error = "Gemini API key is not configured", connectionState = ConnectionState.DISCONNECTED) }; return }; client?.disconnect(); audioEngine?.release(); modelSpeaking = false; _state.update { it.copy(connectionState = ConnectionState.CONNECTING, error = null, inputLevel = 0f, outputLevel = 0f) }; audioEngine = AudioEngine({ chunk -> if (!modelSpeaking) client?.sendAudioChunk(chunk) }, { level -> _state.update { it.copy(inputLevel = level) } }, { level -> _state.update { s -> s.copy(outputLevel = level, connectionState = if (level > 0.03f) ConnectionState.SPEAKING else s.connectionState) } }); val voice = settings.selectedVoiceSpeaker.takeIf { it.isNotBlank() } ?: "Kore"; client = GeminiLiveClient(apiKey = apiKey, voiceName = voice, callbacks = object : GeminiLiveClient.Callbacks { private var currentUserId: String? = null; private var currentAnuId: String? = null; override fun onConnected() { audioEngine?.startPlayback(); audioEngine?.startRecording(); modelSpeaking = false; _state.update { it.copy(connectionState = ConnectionState.LISTENING, error = null) } }; override fun onDisconnected() { modelSpeaking = false; audioEngine?.stopRecording(); _state.update { it.copy(connectionState = if (prefs.getBoolean("active", false)) ConnectionState.CONNECTING else ConnectionState.DISCONNECTED) } }; override fun onError(message: String) { modelSpeaking = false; audioEngine?.stopRecording(); _state.update { it.copy(error = message, connectionState = ConnectionState.DISCONNECTED, isAnuResponding = false) } }; override fun onAudioChunk(base64Pcm: String) { if (!modelSpeaking) { modelSpeaking = true; audioEngine?.stopRecording(); _state.update { it.copy(connectionState = ConnectionState.SPEAKING) } }; audioEngine?.playChunkBase64(base64Pcm) }; override fun onUserText(text: String) { val clean = text.removePrefix("You:").removePrefix("You :").trim(); if (clean.isBlank()) return; ProactiveEventEngine.noteUserActivity(); val last = _state.value.chatMessages.lastOrNull(); if (last != null && last.id == currentUserId && last.role == ChatRole.USER) { val updated = last.copy(text = clean); _state.update { s -> s.copy(chatMessages = s.chatMessages.dropLast(1) + updated) }; scope.launch { repository.updateChatMessage(updated) } } else { val id = UUID.randomUUID().toString(); currentUserId = id; val msg = ChatMessage(id, ChatRole.USER, clean, System.currentTimeMillis()); _state.update { s -> s.copy(chatMessages = s.chatMessages + msg) }; scope.launch { repository.saveChatMessage(msg) } } }; override fun onModelText(text: String) { val clean = text.removePrefix("You:").removePrefix("You :").trim(); if (clean.isBlank()) return; val last = _state.value.chatMessages.lastOrNull(); if (last != null && last.id == currentAnuId && last.role == ChatRole.ANU) { val updated = last.copy(text = (last.text + " " + clean).trim()); _state.update { s -> s.copy(chatMessages = s.chatMessages.dropLast(1) + updated, isAnuResponding = false) }; scope.launch { repository.updateChatMessage(updated) } } else { val id = UUID.randomUUID().toString(); currentAnuId = id; val msg = ChatMessage(id, ChatRole.ANU, clean, System.currentTimeMillis()); _state.update { s -> s.copy(chatMessages = s.chatMessages + msg, isAnuResponding = false) }; scope.launch { repository.saveChatMessage(msg) } } }; override fun onInterrupted() { modelSpeaking = false; currentAnuId = null; audioEngine?.flushPlayback(); audioEngine?.startRecording(); _state.update { it.copy(connectionState = ConnectionState.LISTENING, outputLevel = 0f, isAnuResponding = false) } }; override fun onTurnComplete() { currentUserId = null; currentAnuId = null; _state.update { it.copy(isAnuResponding = false) }; audioEngine?.whenPlaybackDrained { if (prefs.getBoolean("active", false) && client != null) { modelSpeaking = false; audioEngine?.startRecording(); _state.update { it.copy(connectionState = ConnectionState.LISTENING, outputLevel = 0f) } } } }; override fun onToolCall(name: String, args: JSONObject, id: String) { client?.sendToolResponse(name, id, executeTool(name, args)) } }); client?.connect(buildSystemInstruction(), buildToolDeclarations()) }
    private fun executeTool(name: String, args: JSONObject): String = when (name) { "openWebsite" -> { val url = args.optString("url").trim(); val label = args.optString("name", url); if (url.isBlank()) "invalid URL" else runCatching { app.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }); "opened $label" }.getOrElse { "could not open $label: ${it.message ?: "unknown error"}" } }; "openApp" -> phoneControls.openApp(args.optString("appName")); "phoneAction" -> when (args.optString("action").trim().lowercase()) { "take_selfie", "selfie", "camera_selfie" -> phoneControls.takeSelfie(); "camera", "open_camera" -> phoneControls.openCamera(); "phone" -> phoneControls.openPhone(); "messages" -> phoneControls.openMessages(); "settings" -> phoneControls.openSettings(); "wifi_settings", "wifi" -> phoneControls.openWifiSettings(); "bluetooth_settings", "bluetooth" -> phoneControls.openBluetoothSettings(); "flashlight_on" -> phoneControls.flashlight(true); "flashlight_off" -> phoneControls.flashlight(false); "volume_up" -> phoneControls.volumeUp(); "volume_down" -> phoneControls.volumeDown(); "brightness_up" -> phoneControls.changeBrightness(10); "brightness_down" -> phoneControls.changeBrightness(-10); else -> "unsupported phone action: ${args.optString("action")}" }; "accessibilityAction" -> phoneControls.accessibilityAction(args.optString("action"), args.optString("text"), args.optString("value")); "getDeviceInfo" -> DeviceInfoProvider.snapshot(app); else -> "Unknown tool: $name" }
    private fun buildToolDeclarations(): JSONArray {
        fun prop(type: String, description: String) = JSONObject().put("type", type).put("description", description)
        val phone = JSONObject().put("name", "phoneAction").put("description", "Execute a phone action. For a selfie ALWAYS use take_selfie; it performs open camera -> front camera -> shutter -> verification.").put("parameters", JSONObject().put("type", "OBJECT").put("properties", JSONObject().put("action", prop("STRING", "take_selfie, camera, phone, messages, settings, flashlight_on, flashlight_off, volume_up, volume_down, brightness_up, brightness_down"))).put("required", JSONArray().put("action")))
        val appTool = JSONObject().put("name", "openApp").put("description", "Open an installed Android app by name.").put("parameters", JSONObject().put("type", "OBJECT").put("properties", JSONObject().put("appName", prop("STRING", "Installed app name"))).put("required", JSONArray().put("appName")))
        val web = JSONObject().put("name", "openWebsite").put("description", "Open a website in the user's browser.").put("parameters", JSONObject().put("type", "OBJECT").put("properties", JSONObject().put("url", prop("STRING", "Full URL")).put("name", prop("STRING", "Human-readable name"))).put("required", JSONArray().put("url")))
        val access = JSONObject().put("name", "accessibilityAction").put("description", "Use Anu Accessibility to click, type, scroll, or perform global actions.").put("parameters", JSONObject().put("type", "OBJECT").put("properties", JSONObject().put("action", prop("STRING", "click, clicktext, longclick, longclicktext, settext, type, scrollforward, scrollbackward, home, back, recents, notifications, quicksettings, power, lock")).put("text", prop("STRING", "Visible target label/text")).put("value", prop("STRING", "Text to enter"))).put("required", JSONArray().put("action")))
        val device = JSONObject().put("name", "getDeviceInfo").put("description", "Read fresh local device information such as battery, RAM, storage, CPU, GPU, India time, and location.").put("parameters", JSONObject().put("type", "OBJECT").put("properties", JSONObject()))
        return JSONArray().put(phone).put(appTool).put(web).put(access).put(device)
    }
    private fun buildSystemInstruction(): String { val language = when (_state.value.language) { ZoyaLanguage.ODIA -> "Odia"; ZoyaLanguage.HINDI -> "Hindi"; ZoyaLanguage.SANTALI -> "Santali"; ZoyaLanguage.ENGLISH -> "English" }; val vision = if (_state.value.isVisionActive) "LIVE VISION ON: current camera frames are current visual evidence." else "LIVE VISION OFF: Anu cannot currently see through the camera; previous observations are PAST/HISTORICAL only."; return "You are Anu, a proactive personal Android assistant. Respond naturally in $language. $vision Never claim current visual access when Live Vision is OFF. There is NO artificial 25-second response timer and NO general response cooldown. Respond as soon as the Live session can process the request. For multi-step device tasks, continue until the requested end state is actually reached. For \"open camera and take a selfie\", ALWAYS call phoneAction(action=take_selfie); do not stop at open camera and do not claim success unless the tool confirms the shutter action. For reminders, the app scheduler is authoritative; when a reminder alarm fires, speak it immediately through Gemini Live. Never use Android system TTS. All assistant speech must come from the configured Gemini Live audio voice." }
    private fun isConnected() = client != null && _state.value.connectionState != ConnectionState.DISCONNECTED
    private fun reconnect() { client?.disconnect(); connectInternal() }
    private fun ensureInitialized() { if (!initialized) initialize(app) }
    private fun startForegroundService() { val intent = Intent(app, ZoyaForegroundService::class.java).setAction(ZoyaForegroundService.ACTION_START); runCatching { ContextCompat.startForegroundService(app, intent) }.onFailure { runCatching { app.startService(intent) } } }
    private fun stopForegroundService() { runCatching { app.startService(Intent(app, ZoyaForegroundService::class.java).setAction(ZoyaForegroundService.ACTION_STOP)) } }
}
